  r.coverage=c.coverage;r.generalizationWins=c.generalization.candidateWins;r.reload=true;r.actorSpecificHints=true;r.noCrossLearnerMutation=true
 end,debug.traceback)
 r.status=ok and 'PASS' or 'FAIL';r.error=not ok and err or nil;D.Content:save(out,D.json.encode(r))
